const t = (number, title, slug, query, intent, group, focus, measure, decision) => ({
  number,
  title,
  slug,
  query,
  intent,
  group,
  focus,
  measure,
  decision,
});

const topics = [
  t(86,"How to Read a Water-Test Report","how-to-read-water-test-report","how to read a water test report","Educational","testing","A report is a snapshot of named parameters, methods, units, detection limits, and comparison values; it is not a universal pass-or-fail certificate for everything that could be in water.","Confirm the sample location and date, then review each result, unit, reporting limit, reference value, and laboratory note. Separate health-based standards from secondary aesthetic guidance.","Ask the laboratory or local health department about unfamiliar results, confirm an unexpected exceedance with a properly collected sample, and select treatment only for verified targets."),
  t(87,"How Often to Test Private Well Water","how-often-test-well-water","how often test private well water","Educational","testing","Private wells are not routinely monitored like public systems, so the owner needs a repeatable testing schedule and event-based triggers.","CDC and EPA recommend annual checks that include total coliform bacteria, nitrate, total dissolved solids, and pH, with additional parameters based on local risks and household circumstances.","Test again after flooding, well or plumbing work, an unexplained change in taste or appearance, or a nearby contamination event; use a state-certified laboratory."),
  t(88,"What to Test for in Private Well Water","private-well-water-testing-list","what to test for in well water","Educational","testing","The right panel depends on geology, nearby land use, the well's age and construction, household vulnerability, and the symptoms that prompted testing.","Start with annual baseline parameters recommended by public-health agencies, then ask the local health department about regionally relevant metals, minerals, bacteria, nitrate, radon, pesticides, or other analytes.","Do not buy a broad treatment package before the target and concentration are known; preserve laboratory records so changes can be compared over time."),
  t(89,"Seasonal Changes in Well Water","seasonal-well-water-changes","well water changes after rain or season","Educational","testing","Rainfall, drought, recharge, runoff, and changing household demand can alter turbidity, yield, taste, odor, or measured chemistry without identifying a single cause.","Document when the change occurs, inspect the wellhead and drainage, and sample while the condition is present using the laboratory's instructions.","Compare results with an earlier baseline, correct sanitary or drainage defects first, and size treatment for the measured range rather than one convenient sample."),
  t(90,"How to Read Asheville's Consumer Confidence Report","asheville-water-quality-report-guide","Asheville water quality report","Educational","municipal","A consumer confidence report summarizes regulated source and finished-water monitoring for a public system; it does not describe every home's premise plumbing or every unregulated compound.","Match the service address to the correct supplier and reporting year, then review detected levels, regulatory limits, violation notices, source information, and special health language.","Use the report to define questions, and test at the tap when the concern could arise from building plumbing, a private service line, or a point-of-use condition."),
  t(91,"How the Complimentary Personalized Water Report Works","personalized-water-quality-report","personalized water quality report Asheville","Service","treatment","A useful recommendation connects the home's water source, available test evidence, household goals, plumbing conditions, and equipment performance claims.","Provide the water source, recent laboratory or utility results, symptoms, household demand, photos of the installation area, and the result you want to achieve.","The proposed equipment should name each treatment job, operating limit, flow assumption, maintenance task, and verification step before installation is scheduled."),
  t(92,"How to Collect a Water Sample","how-to-collect-water-sample","how to collect well water sample","Educational","testing","Sampling technique can change a result, especially for bacteria, metals, volatile compounds, or samples intended to represent a specific fixture or the untreated well.","Use the laboratory's supplied container and instructions, choose the specified sampling point, remove attachments only when directed, avoid touching the container interior, and observe preservation and holding-time requirements.","Label the bottle immediately, maintain any required temperature, document treatment bypass status, and deliver it within the laboratory's specified window."),
  t(93,"Choosing a Certified Water-Testing Laboratory","certified-water-testing-lab","certified well water testing lab North Carolina","Educational","testing","Laboratory certification is tied to methods and analytes, so a lab that performs one water test is not automatically certified for every requested parameter.","Confirm state certification for the exact analytes, the reporting limits, sample containers, preservation steps, turnaround time, chain-of-custody needs, and whether interpretation support is available.","Choose the panel with the health department or another qualified professional, and retain the full report rather than only a verbal summary."),
  t(94,"Choosing Treatment After a Water Test","water-treatment-after-testing","water treatment after well test","Service","treatment","A detected substance does not automatically identify one treatment device; concentration, water chemistry, flow, and the exact product's verified reduction claim all matter.","Confirm unexpected health-related results and record pH, hardness, turbidity, competing substances, peak flow, and treatment location before comparing systems.","Match certified product claims to the measured target, correct source or well defects when possible, and plan post-installation testing to verify performance."),
  t(95,"Home Water Treatment Maintenance Calendar","water-treatment-maintenance-calendar","water treatment maintenance schedule","Educational","treatment","A calendar should follow manufacturer instructions and actual water use rather than treating every cartridge, lamp, membrane, media bed, or softener as if it has the same lifespan.","Inventory model numbers, installation dates, pressure readings, settings, consumables, alarms, sanitation requirements, and prior service records.","Schedule inspections and replacements, record completed work, and investigate early pressure loss, breakthrough, odor, leaks, or unusual consumption instead of simply resetting a reminder."),

  t(101,"Water Pressure and Whole-Home Filtration","water-pressure-whole-home-filtration","whole house water filter pressure drop","Service","treatment","Pressure loss can come from undersized housings, loaded media, small piping, restrictive valves, high peak demand, or a weak source rather than filtration as a category.","Measure static and flowing pressure before and after the system at a known flow, note cartridge age, and compare the readings with the product's pressure-drop data.","Choose equipment for peak service flow, provide gauges and bypass access, and correct source or plumbing limitations that filtration cannot solve."),
  t(102,"How Long Do Whole-House Water Filters Last?","how-long-whole-house-water-filters-last","how long whole house water filter lasts","Educational","treatment","Service life depends on contaminant load, water use, flow, media quantity, pretreatment, and the capacity definition used by the manufacturer.","Track gallons or time, pressure differential, water-quality change, backwash behavior, and the exact model's replacement criteria.","Replace or service based on documented limits and observed performance; do not rely on a universal month count for all homes."),
  t(103,"Water Softener Salt Use Explained","water-softener-salt-use","how much salt does water softener use","Educational","treatment","Salt use reflects hardness load, water consumption, programmed capacity, resin volume, regeneration settings, and system efficiency.","Record inlet hardness including compensated iron when the manufacturer requires it, household gallons, regeneration frequency, salt dose, and unexplained continuous flow.","Compare actual consumption with the programmed design, fix leaks and settings errors, and use an efficient demand-initiated configuration supported by the equipment."),
  t(104,"Why a Water Softener Uses Too Much Salt","water-softener-uses-too-much-salt","water softener using too much salt","Problem","treatment","Excess salt use can follow an incorrect hardness setting, water leak, frequent manual regeneration, stuck control, brine problem, low capacity, or a change in household demand.","Check the meter, regeneration history, hardness setting, salt dose, brine level, drain flow, and untreated and treated hardness.","Correct the identified cause rather than reducing salt blindly, because an under-dosed system can deliver hard water and foul resin."),
  t(105,"Water Softener Regeneration Explained","water-softener-regeneration-explained","water softener regeneration cycle","Educational","treatment","Regeneration restores ion-exchange capacity through staged backwash, brine draw, rinse, and refill steps whose order and timing depend on the valve.","Record when cycles occur, how much water and salt are used, whether flow reaches the drain, and whether the unit meters demand accurately.","Program capacity and salt dose from water conditions and manufacturer data, and investigate cycles that stall, repeat, or fail to restore soft water."),
  t(106,"Water Softener Is Not Making Soft Water","water-softener-not-making-soft-water","water softener not making water soft","Problem","treatment","Hard water after a softener can result from an empty or bridged brine tank, bypass position, exhausted capacity, incorrect programming, resin fouling, or untreated fixtures.","Test hardness before and after the unit, inspect bypass valves and salt condition, and review meter and regeneration history.","Restore normal brining and programming first, then assess resin condition or sizing if hardness leakage continues."),
  t(107,"Water Softener Salt Bridge: Signs and Fixes","water-softener-salt-bridge","water softener salt bridge","Problem","treatment","A hardened crust can make a brine tank look full while preventing salt below it from dissolving properly.","Look for a hollow space beneath the surface without striking the tank or components, and verify that water level changes during regeneration.","Break a confirmed bridge carefully according to manufacturer guidance, remove unsuitable salt debris, and address humidity or overfilling that encourages recurrence."),
  t(108,"Water Softener Brine Tank Has Too Much Water","water-softener-brine-tank-too-much-water","water softener brine tank full of water","Problem","treatment","High brine water can follow a blocked injector, restricted drain, float problem, leaking valve, kinked line, or interrupted regeneration.","Inspect line routing, drain flow, injector condition, float movement, error codes, and the point where the cycle stops.","Do not repeatedly bail out the tank without finding the failure; service the control and confirm a complete regeneration afterward."),
  t(109,"Water Softener Running Constantly","water-softener-running-constantly","water softener keeps running","Problem","treatment","A unit that never leaves regeneration can waste water and may indicate a stalled motor, damaged piston or seal, control fault, or drain restriction.","Identify the active cycle, listen for motor movement, check the display and drain, and place the unit in bypass if leakage or uncontrolled discharge creates risk.","Arrange valve-specific service and verify normal cycle advancement before returning the system to operation."),
  t(110,"Water Softener Resin Replacement Guide","water-softener-resin-replacement","when replace water softener resin","Educational","treatment","Resin age alone does not prove failure; oxidation, iron fouling, hydraulic damage, chlorine exposure, and operating history affect performance.","Compare inlet and outlet hardness after a complete regeneration, review capacity loss, pressure drop, resin appearance when professionally inspected, and water chemistry.","Clean only when appropriate for the foulant and resin, or replace resin when verified capacity or physical condition no longer supports reliable service."),
  t(111,"Water Softener Bypass Valve Explained","water-softener-bypass-valve","water softener bypass valve","Educational","treatment","A bypass isolates treatment for service or troubleshooting, but valve styles differ and a partially positioned bypass can blend hard water or restrict flow.","Identify the model, label service and bypass positions, and verify which fixtures receive treated water.","Exercise the valve only as instructed, repair leaks or stiffness, and retest treated hardness after returning it fully to service."),
  t(112,"Water Softener Leaking: What to Check","water-softener-leaking","water softener leaking","Problem","treatment","Leaks may originate at connectors, bypass seals, valve components, the brine line, drain line, tank neck, or nearby plumbing.","Shut off or bypass safely, dry the area, observe the exact source and cycle timing, and document pressure and recent work.","Replace the failed component with model-compatible parts and correct excessive pressure or unsupported piping that could cause another leak."),
  t(113,"Water Softener Makes Water Taste Salty","water-softener-salty-water","why does softened water taste salty","Problem","treatment","Noticeably salty water is not a normal softener outcome and can follow incomplete rinse, a blocked drain or injector, incorrect assembly, or unusually high sodium contribution.","Bypass the unit for comparison, check cycle completion and drain flow, and test chloride or sodium if the concern persists.","Service the regeneration problem and flush as directed; people on sodium-restricted diets should discuss drinking-water choices with a qualified health professional."),
  t(114,"Water Softener Sizing for Household Demand","water-softener-sizing-household","how to size a water softener","Service","treatment","Sizing requires more than bedroom count because hardness, iron, daily gallons, peak flow, reserve strategy, salt efficiency, and resin volume work together.","Use a current water analysis and realistic occupancy, fixture, and usage data rather than an oversized capacity label.","Compare usable capacity at the proposed salt dose, service flow, regeneration interval, pressure loss, and plumbing compatibility."),
  t(115,"Can a Water Softener Remove Iron?","can-water-softener-remove-iron","does water softener remove iron","Educational","treatment","Some softeners publish limited dissolved-iron capability, but iron form, concentration, pH, oxygen, bacteria, and resin-cleaning needs determine whether that approach is suitable.","Test total iron and related chemistry, observe whether particles or slime are present, and check the exact model's operating limits.","Use dedicated iron treatment when conditions exceed verified softener capability, and protect downstream resin from avoidable fouling."),

  t(116,"Whole-House Filter Sizing by Flow Rate","whole-house-filter-flow-rate-sizing","whole house water filter flow rate sizing","Service","treatment","A filter must meet peak simultaneous demand without excessive pressure loss while providing enough contact time or surface area for its treatment job.","Estimate fixture demand, measure available source flow and pressure, note pipe diameter, and review certified service-flow and pressure-drop data.","Size the housing, media, valves, and bypass as a system rather than selecting only by port size or advertised maximum flow."),
  t(117,"Where to Install a Whole-House Water Filter","whole-house-filter-installation-location","where to install whole house water filter","Educational","treatment","The location affects which fixtures are treated, freeze and flood risk, drainage, electricity, service clearance, and protection of water heaters or other equipment.","Map the main line, shutoff, pressure tank or meter, outdoor branches, drain route, and treatment sequence before cutting pipe.","Provide a bypass, gauges, isolation, leak protection where appropriate, and enough room to remove cartridges or media safely."),
  t(118,"Whole-House Filter Before or After Water Softener?","filter-before-or-after-water-softener","whole house filter before or after softener","Comparison","treatment","System order depends on what each stage removes, its operating limits, and which device needs protection; there is no universal filter-first rule.","Identify sediment, chlorine, iron, hardness, pH, and disinfectant compatibility, then review each product's inlet requirements and backwash needs.","Sequence equipment so pretreatment protects sensitive media without starving flow, and include sampling points to verify each stage."),
  t(119,"Whole-House Water Filter Is Clogging Quickly","whole-house-filter-clogging-quickly","whole house water filter clogs quickly","Problem","treatment","Rapid loading can reveal a high sediment event, undersized surface area, overly fine rating, pipe scale, oxidized metals, biological material, or overdue source maintenance.","Inspect the captured material, measure pressure differential, note weather or plumbing changes, and test relevant water parameters.","Correct the source where possible and consider staged or self-cleaning pretreatment sized for the actual particle load."),
  t(120,"Whole-House Filter Causes Low Water Pressure","whole-house-filter-low-pressure","whole house filter low water pressure","Problem","treatment","Low pressure after filtration may be a loaded cartridge, closed valve, undersized housing, restrictive media, high demand, or a pre-existing pump or plumbing limitation.","Compare static and flowing pressure on both sides at known flow, inspect bypass position, and check service age.","Replace or service the loaded element and resize only after confirming the source can provide the required flow."),
  t(121,"Carbon Filter Capacity Explained","carbon-filter-capacity-explained","whole house carbon filter capacity","Educational","treatment","Carbon capacity varies by target compound, influent concentration, contact time, flow, carbon type, and the breakthrough level used in testing.","Review the exact product's certified claims and rated capacity, then estimate household gallons and monitor the target condition.","Replace or rebid media before verified capacity is exhausted; taste alone is not a safe monitor for every compound."),
  t(122,"Catalytic Carbon for Chloramine","catalytic-carbon-chloramine","catalytic carbon filter for chloramine","Educational","treatment","Chloramine is more persistent than free chlorine, and reduction performance depends on catalytic media, contact time, flow, water chemistry, and product-specific certification.","Confirm the utility disinfectant and residual, then review the exact system's chloramine claim, service flow, capacity, and sampling method.","Size for realistic peak demand and verify residual after installation rather than assuming any carbon tank will perform equally."),
  t(123,"Sediment Filter Cartridge Types Compared","sediment-filter-cartridge-types","sediment filter cartridge types","Comparison","treatment","Spun, pleated, string-wound, melt-blown, and depth cartridges differ in dirt-holding pattern, cleanability, rating, material, and flow behavior.","Identify particle size and load, compare nominal versus absolute ratings, housing dimensions, pressure drop, and temperature or chemical compatibility.","Choose the least restrictive cartridge that meets the actual goal and use differential pressure or observed loading to guide changes."),
  t(124,"Nominal vs. Absolute Micron Ratings","nominal-vs-absolute-micron-rating","nominal vs absolute micron filter","Comparison","treatment","Micron size alone is incomplete because nominal and absolute ratings use different efficiency definitions and test methods.","Request the manufacturer's removal efficiency at a stated particle size, test method, flow, and pressure-drop curve.","Compare products on documented performance and system needs, not simply the smallest number printed on a package."),
  t(125,"Backwashing Filter Drain Requirements","backwashing-filter-drain-requirements","backwashing water filter drain requirements","Educational","treatment","Backwashing media needs a temporary high flow to lift and clean the bed, creating discharge that must reach an approved drain without backpressure.","Check required backwash rate, duration, frequency, drain size, air gap, elevation, freezing exposure, septic considerations, and available well flow.","Design drainage and supply capacity before equipment selection; a media tank that cannot backwash correctly may channel or foul."),
  t(126,"Water Filter Bypass and Isolation Valves","water-filter-bypass-isolation-valves","whole house filter bypass valves","Educational","treatment","A well-planned bypass and isolation arrangement allows service without leaving the home unexpectedly without water or forcing flow through an unsafe leak.","Label valve positions, include gauges and sampling points, and confirm check valves or pressure controls will not trap pressure.","Test the bypass during commissioning and document the safe shutdown procedure for the homeowner."),
  t(127,"Should Outdoor Faucets Use Filtered Water?","outdoor-faucets-filtered-water","should outdoor faucets bypass water filter","Educational","treatment","Treating irrigation or hose water can consume capacity and reduce available indoor flow, while some outdoor uses may benefit from treatment depending on the goal.","Map outdoor branches and identify uses such as drinking, vehicle washing, irrigation, pools, or livestock before routing them.","Bypass unnecessary high-volume loads where plumbing permits, while keeping any health-related use aligned with tested water quality."),
  t(128,"Whole-House Filter Maintenance Costs","whole-house-filter-maintenance-costs","whole house water filter maintenance cost","Cost","treatment","Ownership cost includes replacement cartridges or media, service labor, water used for backwash, electricity, testing, sanitation, and disposal—not only the purchase price.","Estimate annual gallons, local water conditions, consumable price and availability, service interval, warranty exclusions, and access difficulty.","Compare a realistic multi-year operating plan and avoid invented universal prices that ignore system size and contaminant load."),
  t(129,"Water Filter Certification Labels Explained","water-filter-certification-labels","water filter NSF certification explained","Educational","treatment","Certification applies to a named product and claim under a defined standard; a component carrying a mark does not automatically certify the assembled system for every reduction claim.","Look up the exact model in the certifier's public database and match the contaminant, capacity, flow, and replacement element.","Treat vague phrases such as tested to a standard differently from independently certified to a specific reduction claim."),
  t(130,"How to Verify Water Filter Performance","verify-water-filter-performance","how to test if water filter works","Educational","testing","Verification should measure the parameter that justified treatment at the correct sampling points and time, not rely only on clearer appearance or improved taste.","Collect untreated and treated samples with the same appropriate method, record flow and system age, and use a certified laboratory when health-related contaminants are involved.","Compare results with product claims and action levels, investigate breakthrough or sampling error, and retain data for future maintenance decisions."),

  t(131,"Orange Stains from Well Water","orange-stains-well-water","orange stains from well water","Problem","testing","Orange or brown staining can involve iron, sediment, pipe corrosion, or combinations, and appearance does not reveal concentration or iron form.","Test iron, manganese, pH, hardness, and turbidity, and note whether water is clear at first or already carries particles.","Choose oxidation, filtration, softening, or plumbing correction only after the source and operating limits are established."),
  t(132,"Black Stains from Well Water","black-stains-well-water","black stains from well water","Problem","testing","Black staining may involve manganese, plumbing materials, sediment, or biological growth and should not be diagnosed by color alone.","Test manganese, iron, pH, hardness, and relevant microbiological parameters while documenting fixture location and timing.","Address verified chemistry and inspect plumbing or water-heater contributions before selecting treatment."),
  t(133,"Blue-Green Stains and Acidic Water","blue-green-stains-acidic-water","blue green stains well water","Problem","testing","Blue-green stains can be consistent with copper corrosion, which may be influenced by low pH, alkalinity, stagnation, temperature, and plumbing age.","Test first-draw and flushed copper where appropriate, plus pH and alkalinity, using laboratory instructions designed for corrosion evaluation.","Consult the health department about elevated copper and correct corrosive conditions and plumbing sources with post-correction verification."),
  t(134,"Cloudy Well Water That Clears","cloudy-well-water-clears","cloudy well water clears in glass","Problem","testing","Cloudiness that clears from bottom to top may be entrained air, while settling particles can indicate sediment; neither observation rules out other concerns.","Observe direction and timing, compare hot and cold taps, check pump or pressure changes, and test turbidity when particles persist.","Repair air-entry or source issues and choose sediment control only for confirmed particulate load."),
  t(135,"Sand or Grit in Well Water","sand-grit-well-water","sand in well water","Problem","testing","Sand or grit can originate from well construction, screen or casing problems, pump placement, aquifer material, or disturbed plumbing deposits.","Capture and inspect material, check which fixtures are affected, and have the well and pump evaluated before relying on cartridges.","Correct mechanical causes where feasible and size separators or filters for measured particle size and load."),
  t(136,"Rotten-Egg Odor in Cold Well Water","rotten-egg-odor-cold-well-water","rotten egg smell cold well water","Problem","testing","Sulfur-like odor in cold water can involve hydrogen sulfide, sulfur bacteria, other microbial activity, or plumbing conditions; odor is not a complete safety test.","Compare untreated, treated, and multiple fixture samples, test relevant chemistry and bacteria, and inspect the well and treatment train.","Select aeration, oxidation, disinfection, filtration, or source correction only after identifying the likely origin and demand."),
  t(137,"Rotten-Egg Odor Only in Hot Water","rotten-egg-odor-hot-water","rotten egg smell hot water only","Problem","testing","Odor confined to hot water often directs attention to the water heater, anode interaction, temperature, stagnation, or microbial activity rather than the well alone.","Compare hot and cold fixtures, inspect heater condition and settings safely, and test when microbial or source concerns remain.","Use qualified plumbing service for heater changes and avoid removing protective components without evaluating corrosion consequences."),
  t(138,"Metallic Taste in Well Water","metallic-taste-well-water","metallic taste well water","Problem","testing","Metallic taste can involve iron, manganese, copper, zinc, low pH, stagnant plumbing, or another source and cannot identify a safe concentration.","Test targeted metals, pH, alkalinity, and first-draw versus flushed samples when premise plumbing may contribute.","Address the verified source, flush stagnant lines as appropriate, and confirm performance with follow-up testing."),
  t(139,"Earthy or Musty Well-Water Odor","earthy-musty-well-water","musty smell well water","Problem","testing","Earthy or musty odor may involve organic material, microbial growth, stagnant plumbing, treatment fouling, or source changes.","Locate whether the odor is at one fixture, hot water, or the untreated supply, then inspect filters and sample as advised by a laboratory or health department.","Sanitize or service confirmed sources and replace exhausted media rather than masking the odor with added stages."),
  t(140,"Low pH in Private Well Water","low-ph-well-water","low pH well water treatment","Problem","testing","Low pH can contribute to corrosive conditions, but treatment design also depends on alkalinity, hardness, carbon dioxide, metals, flow, and finished-water goals.","Measure laboratory pH promptly, alkalinity, hardness, copper, lead where relevant, and the home's peak flow.","Compare calcite, blended media, or chemical-feed designs by correction range, backwash needs, hardness added, maintenance, and verification."),
  t(141,"High Iron and Low pH Together","high-iron-low-ph-well-water","high iron low pH well water","Problem","testing","Low pH can complicate iron treatment and corrosion control, while neutralizing media can change hardness and downstream treatment needs.","Test iron form and concentration, pH, alkalinity, hardness, manganese, turbidity, and flow before sequencing equipment.","Design correction and iron removal as one treatment train, then test between stages and at the tap."),
  t(142,"Manganese in Private Well Water","manganese-private-well-water","manganese in well water treatment","Problem","testing","Manganese can stain dark surfaces and may have health significance at certain concentrations, so visual clues should lead to certified testing and health-department guidance.","Measure manganese, iron, pH, hardness, and competing chemistry with a certified laboratory.","Compare treatment claims at the measured concentration and verify finished water rather than judging only stain reduction."),
  t(143,"Nitrate in Private Well Water","nitrate-private-well-water","nitrate in well water","Problem","testing","Nitrate has no reliable taste, odor, or color warning and is especially important for infant feeding and pregnancy-related household decisions.","Use a certified laboratory, follow sampling instructions, and contact the local health department promptly when results exceed guidance.","Do not boil nitrate-contaminated water; use an appropriate alternate source or verified treatment plan and retest as directed."),
  t(144,"Coliform Bacteria in Well Water","coliform-bacteria-well-water","coliform bacteria in well water","Problem","testing","A total-coliform result indicates a sanitary pathway or sampling concern that warrants confirmation and investigation; E. coli findings require prompt public-health guidance.","Contact the local health department, review sample technique, inspect well construction and drainage, and collect confirmation samples as directed.","Correct the contamination pathway before relying on disinfection equipment, then verify with follow-up laboratory testing."),
  t(145,"Arsenic Testing for Private Wells","arsenic-testing-private-wells","arsenic testing private well","Educational","testing","Arsenic is naturally occurring in some geology and cannot be detected by taste, color, or odor.","Ask the local health department whether arsenic belongs in the local testing panel and use a certified laboratory with an appropriate reporting limit.","Confirm elevated results and compare point-of-use or point-of-entry products using exact certified arsenic-reduction claims and operating conditions."),
  t(146,"Radon in Well Water: Testing Questions","radon-well-water-testing","radon in well water testing","Educational","testing","Radon risk assessment considers indoor air as the primary pathway and may include water testing for homes supplied by groundwater.","Consult the state radon program or health department about test order, methods, timing, and interpretation rather than using an unverified kit result alone.","Coordinate air and water findings before selecting aeration or carbon treatment, and account for off-gassing, exhaust, and media handling."),
  t(147,"Tannins and Tea-Colored Well Water","tannins-tea-colored-well-water","tannins in well water","Problem","testing","Tea or yellow color may involve natural organic matter, iron, sediment, plumbing, or mixed causes, and tannin treatment is sensitive to chemistry.","Test color, iron, manganese, pH, hardness, turbidity, and organic indicators recommended by the laboratory.","Compare anion exchange, oxidation, carbon, or source correction only after separating dissolved color from particles and metals."),
  t(148,"Hardness in Private Well Water","hardness-private-well-water","well water hardness level","Educational","testing","Hardness mainly reflects calcium and magnesium and can affect scale and soap performance, but the number must be interpreted with units and household goals.","Confirm grains per gallon or milligrams per liter as calcium carbonate, plus iron and manganese that may affect softener design.","Size ion exchange from measured load and demand, or compare scale-management alternatives without describing them as true softening."),
  t(149,"Well Water Changes After Pump Replacement","well-water-after-pump-replacement","well water dirty after pump replacement","Problem","testing","Pump work can disturb sediment, change pumping rate, expose sanitary defects, or alter where water enters the system.","Ask the contractor what was changed, flush as directed, inspect persistent particles, and test bacteria after well work according to health guidance.","Do not let a temporary filter hide a casing, screen, pump-placement, or sanitation problem that needs correction."),
  t(150,"Well Water Changes After Plumbing Work","well-water-after-plumbing-work","discolored water after plumbing work","Problem","testing","Shutoffs and pipe work can release scale, solder debris, air, or stagnant water and can also introduce contamination if sanitary practices fail.","Identify affected fixtures, flush safely, inspect aerators, and test targeted metals or bacteria when the work or symptoms warrant it.","Correct plumbing sources and retest before adding permanent treatment for what may be a temporary disturbance."),

  t(151,"Chlorine Taste in City Water","chlorine-taste-city-water","chlorine taste city water filter","Problem","municipal","Disinfectant residual protects distribution systems, and noticeable taste varies with concentration, temperature, stagnation, and individual sensitivity.","Confirm the supplier and disinfectant in the current report, compare multiple taps and times, and ask the utility about unusual changes.","Use a product with the relevant certified reduction claim and replace media before breakthrough; do not remove disinfectant without a maintenance plan."),
  t(152,"Chloramine vs. Chlorine in Municipal Water","chloramine-vs-chlorine-city-water","chloramine vs chlorine water treatment","Comparison","municipal","Free chlorine and chloramine behave differently in distribution and carbon treatment, so the utility's actual disinfectant determines product selection.","Review the current consumer confidence report or utility notice and confirm whether temporary disinfectant changes occur.","Compare exact certified reduction claims, contact time, flow, capacity, and maintenance rather than choosing carbon by tank size alone."),
  t(153,"White Scale on Fixtures with City Water","white-scale-city-water","white scale on faucets city water","Problem","municipal","White deposits often involve hardness minerals left after evaporation, but cleaners, silica, or other residues can look similar.","Review utility hardness information or test at the tap, inspect water-heater scale, and identify whether deposits dissolve with appropriate cleaning.","Choose softening only when hardness reduction is the goal and account for sodium, drainage, salt, and maintenance."),
  t(154,"Cloudy City Water That Clears","cloudy-city-water-clears","cloudy tap water clears","Problem","municipal","Cloudiness that clears from bottom to top is often air released as pressure or temperature changes, while persistent particles or color deserve utility attention.","Observe clearing direction, compare hot and cold taps, and check whether neighbors or the utility report similar work.","Contact the utility for persistent changes and avoid installing filtration before identifying whether the issue is air, plumbing, or supply-related."),
  t(155,"Brown City Water After Utility Work","brown-city-water-utility-work","brown water after water main work","Problem","municipal","Main flushing or repairs can disturb mineral deposits, but customers should follow the utility's specific notice and avoid assumptions about safety.","Check official alerts, avoid laundry or hot-water draw when instructed, and document whether discoloration clears after approved flushing.","Contact the utility if it persists, and inspect premise plumbing only after the supply-side event is resolved."),
  t(156,"Lead at the Tap and Premise Plumbing","lead-at-tap-premise-plumbing","lead in tap water home plumbing","Educational","municipal","A utility report describes system-wide compliance, while lead at a particular tap can depend on service-line and building plumbing materials, stagnation, and corrosion control.","Use a certified laboratory and a sampling plan that distinguishes first-draw from flushed water; ask the utility about service-line records.","Follow public-health guidance for elevated results and choose only products certified for lead reduction while pursuing source replacement where applicable."),
  t(157,"PFAS Questions for Municipal Water Customers","pfas-municipal-water-questions","PFAS city water filter questions","Educational","municipal","PFAS is a group of chemicals with compound-specific monitoring and treatment considerations, so broad marketing claims should be checked against current utility data and regulation.","Review the latest utility report and PFAS disclosures, then identify the exact compounds and concentrations relevant to the concern.","Compare certified product claims for those compounds, capacity and replacement requirements, and verify current EPA and state guidance."),
  t(158,"Reverse Osmosis for City Water","reverse-osmosis-city-water","reverse osmosis for city water","Educational","municipal","RO may be useful for a defined drinking-water goal, but it is not automatically necessary for every municipal customer.","Start with the consumer confidence report and any tap-specific testing, then compare the exact model's certified reductions, recovery, pressure requirements, and output.","Place RO at the point of use for drinking and cooking when its verified capabilities match the goal, and maintain prefilters, membrane, tank, and sanitation."),
  t(159,"Whole-House Carbon for City Water","whole-house-carbon-city-water","whole house carbon filter city water","Educational","municipal","Point-of-entry carbon can address certain disinfectant or organic-compound goals throughout a home, but it also removes residual before premise plumbing and requires disciplined maintenance.","Confirm disinfectant type, target compounds, peak flow, contact time, capacity, drainage if backwashing, and microbial management instructions.","Choose certified performance where available and plan timely media service, bypass, gauges, and post-installation verification."),
  t(160,"Do City-Water Homes Need a Softener?","city-water-need-softener","do I need water softener city water","Educational","municipal","Municipal treatment does not necessarily remove hardness, but whether softening is worthwhile depends on measured hardness, scale impact, preferences, and ownership tradeoffs.","Review utility hardness or test at the tap, then document scale, hot-water efficiency concerns, soap performance, and household demand.","Compare true ion-exchange softening with scale-management products accurately and include salt, drainage, sodium, maintenance, and verified outcomes."),
  t(161,"Apartment Water Filtration Options","apartment-water-filtration-options","apartment water filter options","Educational","municipal","Renters usually need reversible point-of-use choices and landlord approval for plumbing changes, while building-wide conditions remain the owner's responsibility.","Identify the specific drinking-water goal using the utility report or testing, check faucet and space compatibility, and review lease restrictions.","Select a certified countertop, faucet, pitcher, or under-sink product for the target and maintain it on schedule without altering shared systems without permission."),
  t(162,"Water Filter for Refrigerator Ice and Water","refrigerator-water-filter-guide","refrigerator water filter replacement guide","Educational","municipal","Refrigerator filters have model-specific reduction claims and capacities; physical fit does not prove equivalent performance.","Look up the exact appliance and certified replacement, record installation date and gallons, and inspect supply-line sanitation and leaks.","Replace at the manufacturer's trigger or earlier when verified capacity, flow, or water conditions require it, then flush as directed."),
  t(163,"Under-Sink Carbon Filter Buying Guide","under-sink-carbon-filter-guide","under sink carbon water filter guide","Educational","treatment","Under-sink carbon systems differ in contaminant claims, flow, capacity, replacement design, and whether they use a dedicated faucet or full-flow cold line.","Define the target from evidence, verify exact certification, measure available space and pressure, and price authentic replacement cartridges.","Choose adequate flow without sacrificing contact time and sanitize or replace components according to instructions."),
  t(164,"Faucet Filter vs. Countertop Filter","faucet-vs-countertop-water-filter","faucet filter vs countertop filter","Comparison","treatment","Both formats can be convenient point-of-use options, but attachment compatibility, flow, capacity, certified claims, and countertop space differ.","Compare exact models against the target compound, daily volume, cartridge cost, bypass function, and installation limitations.","Prefer the product the household can maintain reliably and do not assume a larger device removes more substances."),
  t(165,"Filtered Water for Cooking and Coffee","filtered-water-cooking-coffee","best filtered water for cooking coffee","Educational","municipal","Taste and mineral content can affect beverages and cooking, while health-related concerns require evidence beyond flavor preference.","Separate aesthetic goals from measured contaminants and consider volume, temperature, scale in appliances, and the filter's certified claims.","Use a convenient point-of-use system sized for daily demand and follow cartridge, cleaning, and food-safe storage instructions."),

  t(166,"Planning a Water-Treatment Equipment Room","water-treatment-equipment-room-planning","water treatment equipment room requirements","Service","treatment","A serviceable installation needs structural support, drainage, power where required, freeze protection, ventilation, lighting, bypass access, and clearance for replacement components.","Map pipe sizes, shutoffs, pressure, peak flow, drain elevation, outlets, floor protection, and the dimensions and service envelopes of each device.","Plan the treatment order and future removal path before installation, and keep chemicals or salt stored safely away from moisture-sensitive equipment."),
  t(167,"Water Treatment for a New Construction Home","new-construction-water-treatment-planning","water treatment new construction home","Service","treatment","New construction offers space and plumbing flexibility, but equipment should still follow the confirmed water source and post-completion testing.","Plan a main-line loop, bypass, drains, power, pressure control, sampling taps, outdoor branches, and point-of-use lines without buying treatment before results.","Commission after the well or municipal connection and plumbing are complete, then document baseline and treated-water data."),
  t(168,"Water Treatment Questions Before Buying a Home","water-treatment-homebuyer-checklist","water treatment questions buying home","Educational","testing","A working-looking system does not establish water safety, remaining media life, correct sizing, or ownership cost.","Identify the source, obtain recent laboratory or utility results, inspect the well and equipment, record models and service history, and test independently when appropriate.","Budget for verified repairs or replacement and avoid relying only on seller statements or a quick taste test."),
  t(169,"Water Treatment Inspection Before Selling a Home","water-treatment-home-sale-inspection","water treatment inspection home sale","Educational","testing","Clear records and functioning equipment can reduce uncertainty, but treatment should not be represented as solving contaminants that were never tested.","Compile source and treated-water reports, permits where relevant, model numbers, warranties, settings, maintenance receipts, and current leak or pressure observations.","Service known defects, disclose accurately, and use qualified laboratory and real-estate guidance for transaction-specific requirements."),
  t(170,"Vacation-Home Water System Startup","vacation-home-water-system-startup","vacation home water system startup","Educational","treatment","Long stagnation can affect taste, disinfectant residual, microbial conditions, seals, tanks, and filters, while freeze shutdowns add plumbing risks.","Inspect for leaks and freeze damage, follow well and treatment startup instructions, flush deliberately, and test when the source or shutdown history warrants it.","Replace overdue consumables, sanitize only by an approved procedure, and record a repeatable opening checklist."),
  t(171,"Vacation-Home Water System Shutdown","vacation-home-water-system-shutdown","vacation home water system winterization","Educational","treatment","Shutdown planning must protect plumbing and treatment equipment from freezing, stagnant water, leaks, power loss, and improper chemical or salt storage.","Follow equipment-specific winterization steps, isolate and drain components as directed, secure power and pumps appropriately, and document valve positions.","Use qualified service when tanks, membranes, UV chambers, or pressurized components require disassembly, and plan safe recommissioning."),
  t(172,"Water Treatment After a Long Vacancy","water-treatment-after-long-vacancy","water treatment after house vacant","Educational","testing","A vacant home's water can stagnate and treatment components can expire or dry out, so turning on a tap is not a complete recommissioning plan.","Inspect plumbing and equipment, review shutdown history, flush according to source and utility guidance, replace overdue components, and test where conditions justify it.","Return systems to service in sequence and verify pressure, leaks, settings, disinfectant or microbiological status, and treated-water performance."),
  t(173,"Water-Treatment Leak Detection and Shutoff","water-treatment-leak-detection-shutoff","water filter leak detector shutoff","Educational","treatment","Treatment equipment introduces fittings, drains, tanks, and service events that benefit from planned containment and automatic or manual shutoff options.","Identify high-consequence leak points, floor drains, finished areas, pressure conditions, sensor placement, power and connectivity needs, and bypass access.","Test sensors and shutoff valves on schedule and ensure the system fails in a safe, understandable state during power or network loss."),
  t(174,"Water Treatment and Septic Systems","water-treatment-septic-system","water softener discharge septic system","Educational","treatment","Backwash and regeneration add hydraulic and sometimes salt loads whose significance depends on equipment efficiency, discharge volume, septic design, soil, and local rules.","Quantify cycle volume and frequency, inspect the drain connection and air gap, and consult local environmental health staff or the septic designer.","Optimize settings without sacrificing treatment and never redirect discharge to an unapproved location merely to avoid evaluation."),
  t(175,"Water Treatment During a Power Outage","water-treatment-power-outage","water treatment system power outage","Educational","emergency","Some filters pass water without power while pumps, UV, chemical feed, controls, and RO booster systems may stop or lose monitoring.","Inventory which components require electricity, how valves fail, whether alarms reset, and what untreated bypass risk exists.","Follow boil-water or utility instructions first, use an alternate source when required, and recommission powered equipment according to the manufacturer."),
  t(176,"Water Treatment Generator Planning","water-treatment-generator-planning","generator for well pump water treatment","Educational","emergency","Generator planning should prioritize the well pump and essential treatment loads while accounting for starting current, voltage, grounding, ventilation, and safe transfer equipment.","List pump and device nameplate loads, identify critical versus deferrable cycles, and have a qualified electrician assess connection and capacity.","Never operate a portable generator indoors or backfeed a panel; test the emergency sequence before an outage."),
  t(177,"Treatment System Sampling Ports","water-treatment-sampling-ports","water treatment sampling ports","Educational","treatment","Sampling taps before, between, and after treatment stages make troubleshooting and performance verification more accurate.","Place accessible ports that avoid stagnant branches and allow representative samples without contaminating bottles or bypassing safety controls.","Label each location, document which stage it represents, and use laboratory-specific sampling procedures."),
  t(178,"Keeping Water-Treatment Service Records","water-treatment-service-records","water treatment maintenance records","Educational","treatment","Records turn maintenance from guesswork into a history of water conditions, settings, consumables, repairs, and verified results.","Track model and serial numbers, installation date, baseline tests, settings, pressure, flow, regeneration counts, cartridge or lamp changes, and service notes.","Store digital copies with reminders and transfer them to future homeowners without including account passwords or unrelated personal data."),
  t(179,"Questions to Ask a Water-Treatment Installer","questions-water-treatment-installer","questions to ask water treatment company","Educational","treatment","A credible proposal should explain the tested problem, treatment mechanism, sizing basis, verified claims, installation scope, maintenance, and how success will be measured.","Ask for licenses relevant to the plumbing work, exact model numbers, certifications, flow and pressure data, warranties, consumables, drain and electrical needs, and post-install testing.","Compare written scopes rather than equipment count or fear-based sales language, and keep copies of all assumptions."),
  t(180,"Comparing Water-Treatment Quotes","compare-water-treatment-quotes","compare water treatment system quotes","Comparison","treatment","Two quotes may use different water data, capacities, treatment goals, plumbing scopes, warranties, and maintenance assumptions, so bottom-line price alone is not comparable.","Normalize the target contaminants, model numbers, service flow, usable capacity, installation details, permits, consumables, labor, testing, and exclusions.","Choose the proposal with a defensible evidence-to-equipment connection and a clear verification and ownership plan."),

  t(181,"Private Well Safety After Flooding","private-well-safety-after-flooding","well water after flooding","Emergency","emergency","Floodwater can enter a well directly or through damaged components, and clear appearance does not establish safety.","Do not use the water for drinking until public-health guidance is followed; inspect the well, use an alternate source, and arrange disinfection and certified testing as directed.","Repair structural and drainage defects first, then obtain satisfactory follow-up results before resuming normal use."),
  t(182,"Well Water After a Major Storm","well-water-after-major-storm","well water safety after storm","Emergency","emergency","Storms can cause flooding, power loss, pressure loss, damaged well components, landslides, and runoff even when the wellhead was not visibly submerged.","Inspect from a safe distance, note outages or pressure loss, follow local advisories, and test when flooding, damage, or water-quality change occurred.","Use alternate water until authorities or qualified testing confirm the appropriate next step, and document repairs and results."),
  t(183,"Boil-Water Advisory and Home Filters","boil-water-advisory-home-filter","does water filter work during boil advisory","Emergency","emergency","Most household filters do not replace a boil-water advisory, and using untreated water can contaminate filter housings, ice makers, appliances, and stored-water components.","Follow the issuing authority's instructions for drinking, cooking, brushing teeth, ice, pets, and vulnerable household members.","After the advisory, flush and sanitize or replace affected components according to utility and manufacturer guidance."),
  t(184,"Recommissioning Filters After a Boil Advisory","filters-after-boil-water-advisory","replace water filter after boil advisory","Emergency","emergency","Whether a cartridge, membrane, tank, refrigerator, or ice maker needs flushing, sanitation, or replacement depends on exposure and manufacturer instructions.","Identify every device that received water during the advisory and obtain current utility and equipment guidance.","Complete the specified sequence only after the advisory is lifted, and do not rely on taste or appearance to judge sanitation."),
  t(185,"Frozen Water-Treatment Equipment","frozen-water-treatment-equipment","water filter froze what to do","Emergency","emergency","Freezing can crack housings, valves, membranes, gauges, tanks, and plumbing even when damage is not immediately visible.","Shut down safely, avoid applying open flame, allow controlled thawing, inspect under pressure only with appropriate precautions, and document leaks or deformation.","Replace compromised pressure components and correct insulation, heat, drainage, or location before returning the system to service."),
  t(186,"Well-Water Testing During Drought","well-water-testing-drought","well water changes during drought","Educational","testing","Drought can lower water levels, change yield and pumping behavior, concentrate some dissolved constituents, or increase sediment without predicting a specific contaminant.","Track yield, pump cycling, depth information if professionally available, and test when water quality or supply changes.","Reduce demand as advised, protect the pump, and design treatment around confirmed conditions that may differ after recharge."),
  t(187,"Spring Well-Water Maintenance Checklist","spring-well-water-maintenance","spring well water checklist","Educational","testing","Spring is a useful time to inspect winter damage, drainage, wellhead condition, treatment records, and the annual testing schedule.","Check the cap, casing, grading, visible wiring and piping, leaks, filters, salt, UV status, pressure, and overdue laboratory work without opening the well unnecessarily.","Correct defects with qualified help and preserve annual results so seasonal changes can be evaluated."),
  t(188,"Fall Water-Treatment Maintenance Checklist","fall-water-treatment-maintenance","fall water treatment checklist","Educational","treatment","Fall preparation reduces freeze risk and catches overdue consumables, drain problems, salt shortages, weak batteries, or service needs before winter access becomes difficult.","Review outdoor exposure, insulation, heat, drainage, leak sensors, generator plans, filters, lamps, salt, and vacation shutdown needs.","Complete manufacturer-specified service and record dates, settings, and spare parts without stockpiling consumables past safe storage limits."),
  t(189,"Water Safety After a Plumbing Pressure Loss","water-safety-after-pressure-loss","water safety after pressure loss","Emergency","emergency","Loss of pressure can allow intrusion under some conditions and may trigger utility or public-health instructions that household filtration cannot override.","Determine whether the event affected a public system, private well, or only premise plumbing; check official notices and identify repairs performed.","Follow flushing, disinfection, boil-water, or sampling guidance from the responsible authority before normal use."),
  t(190,"Emergency Drinking-Water Storage for Homeowners","emergency-drinking-water-storage","emergency drinking water storage home","Emergency","emergency","Stored water provides resilience during outages or advisories, but containers, rotation, location, and treatment instructions determine whether it remains usable.","Follow current emergency-agency guidance for quantity, approved containers, labeling, storage conditions, and replacement dates.","Keep stored water separate from treatment chemicals, protect it from heat and contamination, and follow official disinfection directions when no safe commercial source is available."),
];

const expected = [...Array.from({ length: 10 }, (_, i) => i + 86), ...Array.from({ length: 90 }, (_, i) => i + 101)];
if (topics.length !== 100 || topics.map((x) => x.number).join() !== expected.join()) {
  throw new Error(`Expected IDs 86-95 and 101-190; received ${topics.length} topics.`);
}

const slugs = new Set();
for (const topic of topics) {
  if (slugs.has(topic.slug)) throw new Error(`Duplicate generated slug: ${topic.slug}`);
  slugs.add(topic.slug);
}

const existingFiles = (await readdir(contentDir)).filter((name) => name.endsWith(".md") && !name.startsWith("generated-"));
for (const file of existingFiles) {
  const body = await readFile(join(contentDir, file), "utf8");
  for (const slug of slugs) {
    if (body.includes(`/${slug}/`)) throw new Error(`Slug /${slug}/ already exists in ${file}`);
  }
}

const makeDescription = (topic) => {
  const lead = `${topic.title}: what to check, what to measure, and how to choose a defensible next step for a Western North Carolina home.`;
  return lead.length <= 155 ? lead : `${lead.slice(0, 152).replace(/\s+\S*$/, "")}…`;
};

const render = (topic) => {
  const sources = officialSources[topic.group] || officialSources.treatment;
  return `## ${topic.number}. ${topic.title}
**Slug:** \`/${topic.slug}/\`
**Title tag:** ${topic.title} | Asheville Water Specialists
**Meta description:** ${makeDescription(topic)}
**Query:** ${topic.query}

${topic.focus} The practical goal is to separate an observation from a diagnosis, use the right evidence, and avoid adding equipment that has no defined job.

### What to establish first

${topic.measure} Record the water source, affected fixtures, timing, recent plumbing or well work, weather changes, existing treatment, and household demand. Those details help distinguish a source-water condition from premise plumbing, a water heater, an exhausted filter, or a sampling artifact.

Symptoms such as taste, odor, color, staining, scale, or low pressure can guide an investigation, but they cannot confirm that water is safe. When health-related contaminants or microorganisms are possible, use a state-certified laboratory and follow the local health department's instructions.

### How to compare the next steps

${topic.decision} For any proposed device, record the exact model, treatment mechanism, certified reduction claim where applicable, service flow, capacity, pressure loss, operating limits, wastewater or drainage needs, consumables, and maintenance schedule.

Whole-home and point-of-use systems solve different scopes. Treat the smallest appropriate scope unless the verified concern or household goal applies throughout the plumbing. More stages are not automatically better: each additional stage can add pressure loss, cost, maintenance, and the risk of unnoticed breakthrough.

### Installation, maintenance, and verification

Plan bypass and isolation valves, sampling points, gauges, drainage, electrical needs, service clearance, and protection from freezing or leaks. Plumbing work should be performed in accordance with applicable codes and by appropriately qualified professionals.

After installation or correction, repeat the measurement that justified the work at a representative sampling point. Keep the untreated baseline, treated result, equipment settings, installation date, and service history together. Investigate early breakthrough, unusual salt or water use, pressure loss, leaks, alarms, or recurring symptoms rather than only resetting a timer.

### Authoritative references

${sources.map((source) => `- ${source}`).join("\n")}

These references provide general public guidance. A laboratory, local health department, utility, licensed plumber, or other qualified professional may recommend different steps for a specific property or urgent result.
`;
};

const batches = [
  [86, 95, "generated-07-testing-86-95.md"],
  [101, 115, "generated-08-softeners-101-115.md"],
  [116, 130, "generated-09-filtration-116-130.md"],
  [131, 150, "generated-10-well-water-131-150.md"],
  [151, 165, "generated-11-municipal-151-165.md"],
  [166, 180, "generated-12-planning-166-180.md"],
  [181, 190, "generated-13-seasonal-181-190.md"],
];

await mkdir(contentDir, { recursive: true });
for (const [from, to, filename] of batches) {
  const pages = topics.filter((topic) => topic.number >= from && topic.number <= to);
  const title = `# Ranking-Targeted Guides ${from}-${to}\n\n`;
  await writeFile(join(contentDir, filename), title + pages.map(render).join("\n"), "utf8");
}

console.log(`Generated ${topics.length} reviewed topic pages in ${batches.length} batches.`);
